<?php /* NetMonitor - Payment & Collection PRO */ require_once __DIR__ . '/../Config/database.php'; header('Content-Type: application/json; charset=utf-8'); ini_set('display_errors','0'); function out_json(bool $ok,string $message='',array $data=[],int $code=200):void{http_response_code($code);echo json_encode(array_merge(['success'=>$ok,'message'=>$message],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;} function post_string(string $key,string $default=''):string{return trim((string)($_POST[$key]??$default));} try{$pdo=(new Database())->connect();$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec("SET time_zone='+07:00'");$action=strtolower((string)($_GET['action']??'list')); if($action==='list'){$q=trim((string)($_GET['q']??''));$status=strtolower(trim((string)($_GET['status']??'all')));$month=trim((string)($_GET['month']??''));$where=[];$args=[];if($q!==''){$where[]='(i.invoice_no LIKE ? OR c.name LIKE ? OR c.pppoe_username LIKE ? OR COALESCE(i.payment_method,\'\') LIKE ?)';$like="%$q%";array_push($args,$like,$like,$like,$like);}if($status==='overdue')$where[]="i.status='unpaid' AND i.due_date<CURDATE()";elseif(in_array($status,['unpaid','paid','cancelled'],true)){$where[]='i.status=?';$args[]=$status;}if(preg_match('/^\d{4}-\d{2}$/',$month)){$where[]='i.period BETWEEN ? AND ?';$args[]=$month.'-01';$args[]=date('Y-m-t',strtotime($month.'-01'));}$sql="SELECT i.id,i.invoice_no,i.period,i.amount,i.due_date,i.status,i.paid_at,i.payment_method,i.notes,c.id customer_id,c.name customer_name,c.phone,c.pppoe_username,c.package_name,CASE WHEN i.status='unpaid' AND i.due_date<CURDATE() THEN 1 ELSE 0 END overdue_days_flag,CASE WHEN i.status='unpaid' THEN GREATEST(DATEDIFF(CURDATE(),i.due_date),0) ELSE 0 END days_overdue FROM billing_invoices i JOIN billing_customers c ON c.id=i.customer_id";if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY CASE WHEN i.status=\'unpaid\' AND i.due_date<CURDATE() THEN 0 WHEN i.status=\'unpaid\' THEN 1 ELSE 2 END,i.due_date ASC,i.id DESC LIMIT 500';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$today=$pdo->query("SELECT COUNT(*) cnt,COALESCE(SUM(amount),0) amount FROM billing_invoices WHERE status='paid' AND paid_at>=CURDATE()")->fetch(PDO::FETCH_ASSOC)?:[];$week=$pdo->query("SELECT COUNT(*) cnt,COALESCE(SUM(amount),0) amount FROM billing_invoices WHERE status='paid' AND paid_at>=DATE_SUB(CURDATE(),INTERVAL WEEKDAY(CURDATE()) DAY)")->fetch(PDO::FETCH_ASSOC)?:[];$monthNow=$pdo->query("SELECT COUNT(*) cnt,COALESCE(SUM(amount),0) amount FROM billing_invoices WHERE status='paid' AND paid_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01') AND paid_at<DATE_ADD(LAST_DAY(CURDATE()),INTERVAL 1 DAY)")->fetch(PDO::FETCH_ASSOC)?:[];out_json(true,'',['payments'=>$rows,'collection'=>['today'=>(float)$today['amount'],'today_count'=>(int)$today['cnt'],'week'=>(float)$week['amount'],'week_count'=>(int)$week['cnt'],'month'=>(float)$monthNow['amount'],'month_count'=>(int)$monthNow['cnt']]]);}if($action==='pay'){$id=(int)($_POST['invoice_id']??0);$method=post_string('payment_method','Cash');$notes=post_string('notes');$paidAt=post_string('paid_at');$allowed=['Cash','Transfer','QRIS','E-Wallet','VA','Lainnya'];if(!in_array($method,$allowed,true))$method='Lainnya';if($id<=0)out_json(false,'Invoice tidak valid.',[],422);$pdo->beginTransaction();$st=$pdo->prepare("SELECT id,invoice_no,status,amount FROM billing_invoices WHERE id=? FOR UPDATE");$st->execute([$id]);$inv=$st->fetch(PDO::FETCH_ASSOC);if(!$inv){$pdo->rollBack();out_json(false,'Invoice tidak ditemukan.',[],404);}if($inv['status']==='cancelled'){$pdo->rollBack();out_json(false,'Invoice dibatalkan dan tidak dapat dibayar.',[],422);}if($inv['status']==='paid'){$pdo->commit();out_json(true,'Invoice sudah tercatat lunas.',['already_paid'=>true]);}if($paidAt==='')$paidAt=date('Y-m-d H:i:s');else{$d=DateTime::createFromFormat('Y-m-d\TH:i',$paidAt)?:DateTime::createFromFormat('Y-m-d H:i:s',$paidAt);if(!$d){$pdo->rollBack();out_json(false,'Tanggal pembayaran tidak valid.',[],422);}$paidAt=$d->format('Y-m-d H:i:s');}$up=$pdo->prepare("UPDATE billing_invoices SET status='paid',paid_at=?,payment_method=?,notes=CASE WHEN ?<>'' THEN ? ELSE notes END WHERE id=? AND status='unpaid'");$up->execute([$paidAt,$method,$notes,$notes,$id]);$pdo->commit();out_json(true,'Pembayaran berhasil dicatat.',['invoice_id'=>$id,'invoice_no'=>$inv['invoice_no'],'amount'=>(float)$inv['amount'],'paid_at'=>$paidAt]);}if($action==='unpay'){$id=(int)($_POST['invoice_id']??0);if($id<=0)out_json(false,'Invoice tidak valid.',[],422);$st=$pdo->prepare("UPDATE billing_invoices SET status='unpaid',paid_at=NULL,payment_method=NULL WHERE id=? AND status='paid'");$st->execute([$id]);if(!$st->rowCount())out_json(false,'Invoice tidak ditemukan atau belum berstatus lunas.',[],404);out_json(true,'Pembayaran dibatalkan dan invoice dikembalikan menjadi belum bayar.');}if($action==='summary'){$r=$pdo->query("SELECT COUNT(*) total,COALESCE(SUM(amount),0) amount,SUM(status='paid') paid_count,SUM(status='unpaid') unpaid_count,SUM(status='cancelled') cancelled_count FROM billing_invoices")->fetch(PDO::FETCH_ASSOC)?:[];$today=$pdo->query("SELECT COALESCE(SUM(amount),0) amount,COUNT(*) cnt FROM billing_invoices WHERE status='paid' AND paid_at>=CURDATE()")->fetch(PDO::FETCH_ASSOC)?:[];out_json(true,'',['summary'=>['total'=>(int)$r['total'],'amount'=>(float)$r['amount'],'paid_count'=>(int)$r['paid_count'],'unpaid_count'=>(int)$r['unpaid_count'],'cancelled_count'=>(int)$r['cancelled_count'],'today'=>(float)$today['amount'],'today_count'=>(int)$today['cnt']]]);}out_json(false,'Action tidak dikenal.',[],404);}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();out_json(false,$e->getMessage(),[],500);}
